// Construir contexto del calendario para el prompt de Claude
const items = $input.all();

const calendarContext = items.map(item => {
  const fields = item.json.fields || item.json;
  return {
    tema: fields.tema_principal || 'Sin tema definido',
    subtemas: fields.subtemas || [],
    formato: fields.formato_preferido || 'Video corto',
    publico: fields.publico_objetivo || 'Padres de adolescentes con AACC',
    semana: fields.semana || '',
    pilares: fields.pilares_contenido || []
  };
});

const contextString = calendarContext.map((c, i) =>
  `Entrada ${i + 1}:\n  Tema: ${c.tema}\n  Subtemas: ${Array.isArray(c.subtemas) ? c.subtemas.join(', ') : c.subtemas}\n  Formato: ${c.formato}\n  Pilares: ${Array.isArray(c.pilares) ? c.pilares.join(', ') : c.pilares}`
).join('\n\n');

const fechaActual = new Date().toLocaleDateString('es-ES', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

const prompt = `Eres el estratega de contenido de NOA, una aplicacion para padres de adolescentes con Altas Capacidades Cognitivas (AACC).

Fecha: ${fechaActual}

Contexto del calendario de esta semana:
${contextString || 'Sin entradas especificas en el calendario. Genera ideas basadas en los pilares principales de NOA.'}

Pilares de contenido de NOA:
1. Comprension - Entender como piensa y siente un adolescente con AACC
2. Herramientas - Tecnicas practicas para padres
3. Comunidad - Experiencias compartidas y sentido de pertenencia
4. Esperanza - Historias de exito y progreso
5. Ciencia - Bases neurocienticias y psicologicas

Tono: Empatico, cercano, experto pero accesible. Como un amigo que tambien es especialista.
Formatos disponibles: Video corto TikTok/Reels (60-90s), Carrusel Instagram, Historia, Post texto, Email newsletter.

Genera exactamente 10 ideas de contenido originales y accionables para esta semana.

Responde UNICAMENTE con un JSON valido con esta estructura exacta:
{
  "ideas": [
    {
      "titulo": "Titulo llamativo del contenido (max 80 caracteres)",
      "hook": "Primera frase gancho que para el scroll (max 150 caracteres)",
      "concepto": "Descripcion del concepto en 2-3 oraciones",
      "formato": "Video corto | Carrusel | Historia | Post texto | Email",
      "pilar": "Comprension | Herramientas | Comunidad | Esperanza | Ciencia",
      "angulo_emocional": "Emocion principal que conecta con el padre",
      "palabras_clave": ["keyword1", "keyword2", "keyword3"],
      "urgencia": "Alta | Media | Baja",
      "estimacion_tiempo_produccion": "rapido | medio | complejo"
    }
  ]
}`;

return [{
  json: {
    prompt: prompt,
    calendario_context: calendarContext,
    fecha_generacion: new Date().toISOString(),
    total_entradas_calendario: items.length
  }
}];

// Parsear respuesta de Claude y extraer las 10 ideas
const response = $input.first().json;

if (!response.content || !response.content[0] || !response.content[0].text) {
  throw new Error('Respuesta de Claude invalida o vacia');
}

const rawText = response.content[0].text;

// Extraer JSON de la respuesta (puede venir con texto adicional)
let jsonString = rawText;
const jsonMatch = rawText.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  jsonString = jsonMatch[0];
}

let parsed;
try {
  parsed = JSON.parse(jsonString);
} catch (e) {
  throw new Error(`Error parseando JSON de Claude: ${e.message}\nTexto recibido: ${rawText.substring(0, 500)}`);
}

if (!parsed.ideas || !Array.isArray(parsed.ideas)) {
  throw new Error('La respuesta de Claude no contiene el array de ideas esperado');
}

// Transformar cada idea al formato de Airtable
const fechaHoy = new Date().toISOString().split('T')[0];
const semanaNum = (() => {
  const now = new Date();
  const start = new Date(now.getFullYear(), 0, 1);
  return Math.ceil(((now - start) / 86400000 + start.getDay() + 1) / 7);
})();

const ideasFormateadas = parsed.ideas.map((idea, index) => ({
  json: {
    fields: {
      titulo: idea.titulo || `Idea ${index + 1}`,
      hook: idea.hook || '',
      concepto: idea.concepto || '',
      formato: idea.formato || 'Video corto',
      pilar: idea.pilar || 'Herramientas',
      angulo_emocional: idea.angulo_emocional || '',
      palabras_clave: Array.isArray(idea.palabras_clave) ? idea.palabras_clave.join(', ') : '',
      urgencia: idea.urgencia || 'Media',
      estimacion_produccion: idea.estimacion_tiempo_produccion || 'medio',
      estado: 'BORRADOR',
      fecha_generacion: fechaHoy,
      semana_numero: semanaNum,
      generado_por_ia: true,
      modelo_ia: 'claude-opus-4-5',
      indice_idea: index + 1
    }
  }
}));

return ideasFormateadas;

// Construir resumen de las ideas generadas para notificacion
const ideas = $input.all();

const resumen = ideas.map((item, i) => {
  const f = item.json.fields || item.json;
  return `${i + 1}. *${f.titulo}*\n   Formato: ${f.formato} | Pilar: ${f.pilar} | Urgencia: ${f.urgencia}\n   Hook: _${f.hook}_`;
}).join('\n\n');

const semanaNum = ideas[0]?.json?.fields?.semana_numero || '?';
const fechaHoy = new Date().toLocaleDateString('es-ES', {
  weekday: 'long', day: 'numeric', month: 'long'
});

const mensaje = {
  text: `*NOA Content System - Ideas Semanales Generadas*`,
  blocks: [
    {
      type: 'header',
      text: {
        type: 'plain_text',
        text: '🧠 NOA: 10 Ideas de Contenido Generadas'
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*Semana ${semanaNum}* | ${fechaHoy}\n${ideas.length} ideas listas para revision en Airtable.`
      }
    },
    {
      type: 'divider'
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: resumen
      }
    },
    {
      type: 'actions',
      elements: [
        {
          type: 'button',
          text: { type: 'plain_text', text: 'Ver Ideas en Airtable' },
          url: `https://airtable.com/${process.env.AIRTABLE_BASE_ID || 'BASE_ID'}/Ideas`,
          style: 'primary'
        }
      ]
    }
  ]
};

return [{ json: mensaje }];

// Nodo de manejo de errores - captura y registra errores del workflow
const error = $input.first();

const errorInfo = {
  workflow: 'NOA - Ideas Semanales',
  timestamp: new Date().toISOString(),
  error_message: error.json.message || error.json.error || JSON.stringify(error.json),
  node_error: error.json.node || 'desconocido'
};

console.error('Error en workflow Ideas Semanales:', JSON.stringify(errorInfo));

// Retornar para posible notificacion de error
return [{ json: errorInfo }];

